import{_ as e,a,o as r,a4 as o}from"./chunks/framework.-FZumj2l.js";const l=JSON.parse('{"title":"Cart","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/cart/index.md","filePath":"api/rest-api/shop/cart/index.md","lastUpdated":1783079210000}'),d={name:"api/rest-api/shop/cart/index.md"};function i(s,t,c,n,h,p){return r(),a("div",null,t[0]||(t[0]=[o('<h1 id="cart" tabindex="-1">Cart <a class="header-anchor" href="#cart" aria-label="Permalink to &quot;Cart&quot;">​</a></h1><p>The Cart menu is the shopping basket: create a cart, add and update items, remove items, and apply or remove a coupon. Every response returns the up-to-date cart with its items and recalculated totals, so a client never needs a separate refresh call after a change.</p><h2 id="the-cart-token" tabindex="-1">The cart token <a class="header-anchor" href="#the-cart-token" aria-label="Permalink to &quot;The cart token&quot;">​</a></h2><p>A cart is identified by a <strong>cart token</strong>. Create a cart to obtain it, then send it as <code>Authorization: Bearer &lt;cartToken&gt;</code> on every subsequent cart request (and into checkout). The cart token works for both guests and logged-in customers — guests can build a cart without an account, and the same token carries the cart through checkout.</p><h2 id="coupons" tabindex="-1">Coupons <a class="header-anchor" href="#coupons" aria-label="Permalink to &quot;Coupons&quot;">​</a></h2><p>Apply a coupon code to discount the cart, or remove it to revert. The cart totals in the response reflect the coupon immediately.</p><h2 id="merging-a-guest-cart" tabindex="-1">Merging a guest cart <a class="header-anchor" href="#merging-a-guest-cart" aria-label="Permalink to &quot;Merging a guest cart&quot;">​</a></h2><p>When a shopper builds a cart as a guest and then logs in, merge the guest cart into their customer cart so nothing is lost. Call <a href="/api/rest-api/shop/cart/merge-cart.html">Merge Cart</a> with the <strong>customer</strong> Bearer token and the guest cart&#39;s <code>cart_id</code>: items with the same product and type have their quantities added, other items are copied over, the guest cart is deactivated, and the response is the up-to-date customer cart. Merge requires an authenticated customer (<code>401</code> for a guest) and a valid guest cart id (<code>404</code> otherwise).</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/cart/get-cart.html">Get Cart</a></td><td><code>GET /api/shop/cart</code></td><td>Read the current cart with items and totals.</td></tr><tr><td><a href="/api/rest-api/shop/cart/create-cart.html">Create Cart</a></td><td><code>POST /api/shop/cart</code></td><td>Create a cart and obtain its token.</td></tr><tr><td><a href="/api/rest-api/shop/cart/add-to-cart.html">Add to Cart</a></td><td><code>POST /api/shop/add-product-in-cart</code></td><td>Add a product to the cart.</td></tr><tr><td><a href="/api/rest-api/shop/cart/update-cart-item.html">Update Cart Item</a></td><td><code>PUT /api/shop/update-cart-item</code></td><td>Change an item&#39;s quantity.</td></tr><tr><td><a href="/api/rest-api/shop/cart/remove-cart-item.html">Remove Cart Item</a></td><td><code>DELETE /api/shop/remove-cart-item</code></td><td>Remove an item from the cart.</td></tr><tr><td><a href="/api/rest-api/shop/cart/apply-coupon.html">Apply Coupon</a></td><td><code>POST /api/shop/apply-coupon</code></td><td>Apply a coupon code.</td></tr><tr><td><a href="/api/rest-api/shop/cart/remove-coupon.html">Remove Coupon</a></td><td><code>DELETE /api/shop/remove-coupon</code></td><td>Remove the applied coupon.</td></tr><tr><td><a href="/api/rest-api/shop/cart/merge-cart.html">Merge Cart</a></td><td><code>POST /api/shop/merge-carts</code></td><td>Merge a guest cart into the customer cart after login.</td></tr></tbody></table><p>All Cart endpoints require the storefront key and a cart token (issued by Create Cart) — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',11)]))}const m=e(d,[["render",i]]);export{l as __pageData,m as default};
